var TabSwitcher=function(){"use strict";return{init:function(){document.querySelectorAll(".tabs").forEach(function(t){t.addEventListener("click",function(e){var a=e.target.closest(".tabs__button");if(a){var c=a.getAttribute("data-tab");if(c){t.querySelectorAll(".tabs__button").forEach(function(t){t.classList.remove("active")}),t.querySelectorAll(".tabs__panel").forEach(function(t){t.classList.remove("active")}),a.classList.add("active");var r=t.querySelector("#tab-"+c);r&&r.classList.add("active")}}})})}}}();